import java.util.*;

class TreeNode {

    int val;
    TreeNode left;
    TreeNode right;

    TreeNode(int val) {
        this.val = val;
    }
}

class Codec {

    // Serialize Tree
    public String serialize(TreeNode root) {

        if (root == null) {
            return "";
        }

        StringBuilder sb = new StringBuilder();

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {

            TreeNode node = queue.poll();

            if (node == null) {
                sb.append("null,");
                continue;
            }

            sb.append(node.val).append(",");

            queue.offer(node.left);
            queue.offer(node.right);
        }

        sb.setLength(sb.length() - 1);

        return sb.toString();
    }

    // Deserialize Tree
    public TreeNode deserialize(String data) {

        if (data == null || data.isEmpty()) {
            return null;
        }

        String[] values = data.split(",");

        TreeNode root = new TreeNode(Integer.parseInt(values[0]));

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        int index = 1;

        while (!queue.isEmpty() && index < values.length) {

            TreeNode current = queue.poll();

            if (!values[index].equals("null")) {
                current.left = new TreeNode(Integer.parseInt(values[index]));
                queue.offer(current.left);
            }
            index++;

            if (index < values.length && !values[index].equals("null")) {
                current.right = new TreeNode(Integer.parseInt(values[index]));
                queue.offer(current.right);
            }
            index++;
        }

        return root;
    }

    // Convert tree to level-order string
    private static List<String> levelOrder(TreeNode root) {

        List<String> result = new ArrayList<>();

        if (root == null) {
            return result;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {

            TreeNode node = queue.poll();

            if (node == null) {
                result.add("null");
            } else {

                result.add(String.valueOf(node.val));

                queue.offer(node.left);
                queue.offer(node.right);
            }
        }

        while (!result.isEmpty() &&
                result.get(result.size() - 1).equals("null")) {
            result.remove(result.size() - 1);
        }

        return result;
    }

    public static void main(String[] args) {

        // Custom DevScribe input
        Integer[] root = Input.getIntegerArray("root");

        TreeNode tree = buildTree(root);

        Codec codec = new Codec();

        String serialized = codec.serialize(tree);

        TreeNode deserialized = codec.deserialize(serialized);

        System.out.println("Serialized:");
        System.out.println(serialized);

        System.out.println();

        System.out.println("Deserialized:");
        System.out.println(levelOrder(deserialized));
    }

    // Build tree from level-order array
    private static TreeNode buildTree(Integer[] values) {

        if (values.length == 0 || values[0] == null) {
            return null;
        }

        TreeNode root = new TreeNode(values[0]);

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        int index = 1;

        while (!queue.isEmpty() && index < values.length) {

            TreeNode current = queue.poll();

            if (index < values.length && values[index] != null) {
                current.left = new TreeNode(values[index]);
                queue.offer(current.left);
            }
            index++;

            if (index < values.length && values[index] != null) {
                current.right = new TreeNode(values[index]);
                queue.offer(current.right);
            }
            index++;
        }

        return root;
    }
}
